pub(crate) const HKDF:NativeBinding=NativeBinding{name:"hkdfSha256",parameters:&[NativeParameter{name:"input",..SHA256.parameters[0]},NativeParameter{name:"salt",..SHA256.parameters[0]},NativeParameter{name:"info",..SHA256.parameters[0]},NativeParameter{name:"length",ty:NativeType::Int,access:Mode::Copy,optional:false,rest:false}],result:NativeType::Structured(&Signature::Result(&Signature::Named(NativeTypeId::Bytes),&ERROR)),backend:NativeBackend::Bundled{symbol:"tsrust_crypto_hkdf_sha256"},..SHA256};
pub(crate) const RANDOM_INT:NativeBinding=NativeBinding{name:"randomInt",parameters:&[NativeParameter{name:"min",ty:NativeType::Int,access:Mode::Copy,optional:false,rest:false},NativeParameter{name:"max",ty:NativeType::Int,access:Mode::Copy,optional:false,rest:false}],result:NativeType::Structured(&Signature::Result(&Signature::Int,&ERROR)),backend:NativeBackend::Bundled{symbol:"tsrust_crypto_random_int"},..SHA256};
