const POOL:NativeParameter=NativeParameter{name:"pool",ty:NativeType::Structured(&Signature::Named(NativeTypeId::ThreadPool)),access:Mode::Read,optional:false,rest:false};
const SUBMISSION:NativeParameter=NativeParameter{ty:NativeType::Structured(&Signature::Named(NativeTypeId::PoolSubmission)),access:Mode::Consume,..POOL};
const PASSWORD:NativeParameter=NativeParameter{name:"password",ty:BYTES,access:Mode::Read,optional:false,rest:false};
const ENCODED:NativeParameter=NativeParameter{name:"encoded",ty:NativeType::String,access:Mode::Read,optional:false,rest:false};
const HASH_OPTIONS:NativeParameter=NativeParameter{name:"options",ty:NativeType::Structured(&Signature::Named(NativeTypeId::PasswordHashOptions)),access:Mode::Read,optional:true,rest:false};
const VERIFY_OPTIONS:NativeParameter=NativeParameter{name:"options",ty:NativeType::Structured(&Signature::Named(NativeTypeId::PasswordVerifyOptions)),access:Mode::Read,optional:false,rest:false};
pub(crate) const HASH_PASSWORD:NativeBinding=NativeBinding{name:"hashPassword",parameters:&[POOL,PASSWORD,HASH_OPTIONS],result:NativeType::Structured(&Signature::Result(&Signature::String,&PASSWORD_FAILURE)),backend:NativeBackend::Bundled{symbol:"crypto_password_intrinsic"},features:&["crypto","crypto-password","threads","async","bytes"],..SHA256};
pub(crate) const POLL_HASH_PASSWORD:NativeBinding=NativeBinding{name:"__hashPassword",parameters:&[SUBMISSION,PASSWORD,HASH_OPTIONS],..HASH_PASSWORD};
pub(crate) const VERIFY_PASSWORD:NativeBinding=NativeBinding{name:"verifyPassword",parameters:&[POOL,PASSWORD,ENCODED],result:NativeType::Structured(&Signature::Result(&Signature::Boolean,&PASSWORD_FAILURE)),..HASH_PASSWORD};
