pub(crate) fn password_operation(name:&str)->bool{matches!(name.trim_start_matches('_'),"hashPassword"|"verifyPassword"|"verifyPasswordBounded")}
pub(super) fn lower(expression:&mut crate::syntax::Expr,name:&str,mut args:Vec<crate::syntax::Expr>){use crate::syntax::{Expr,ExprKind};let span=expression.span;let pool=args.remove(0);args.insert(0,Expr::new(ExprKind::Call(Box::new(Expr::new(ExprKind::Name("@native:std:threads#__poolSubmission".into()),span)),vec![pool]),span));crate::stdlib::futures::lazy_result(expression,"std:crypto",&format!("__{name}"),args);}
pub(crate) fn prepare(program:&mut crate::syntax::Program)->Result<(),crate::Diagnostic>{use crate::syntax::ExprKind;let mut used=std::collections::BTreeSet::new();let mut direct=std::collections::HashSet::new();let mut password_used=false;for function in &mut program.functions{crate::source_walk::function_body(function,&mut |_|Ok(()),&mut |expression|{if let ExprKind::Call(callee,args)=&mut expression.kind&&let ExprKind::Name(symbol)=&callee.kind&&let Some(name)=symbol.strip_prefix("@native:std:crypto#")&&password_operation(name){password_used=true;if !name.starts_with('_'){let name=name.to_owned();let args=std::mem::take(args);lower(expression,&name,args);}else{direct.insert(callee.span);}}else if let ExprKind::Name(symbol)=&expression.kind&&let Some(name)=symbol.strip_prefix("@native:std:crypto#")&&password_operation(name)&&!name.starts_with('_')&&!direct.contains(&expression.span){password_used=true;used.insert(name.to_owned());expression.kind=ExprKind::Name(wrappers::name(name));}Ok(())})?;}for name in used{let binding=crate::native_bindings::lookup("std:crypto",&name).expect("registered crypto function");let adapter=wrappers::adapter(program,binding)?;program.functions.push(adapter);}if password_used{for binding in [&HASH_PASSWORD,&POLL_HASH_PASSWORD,&VERIFY_PASSWORD,&POLL_VERIFY_PASSWORD,&VERIFY_BOUNDED,&POLL_VERIFY_BOUNDED]{crate::native_binding_types::prepare(&mut program.records,binding,crate::Span::default())?;}}if program.records.iter().any(|record|record.native_type==Some(NativeTypeId::CryptoHasher)){for binding in [&UPDATE,&FINALIZE]{crate::native_binding_types::prepare(&mut program.records,binding,crate::Span::default())?;}}Ok(())}
